17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Map;
25	import java.util.regex.Pattern;
26	
27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Dedicated audit logger for owner lifecycle side-effects. */
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    /**
67	     * Pragmatic check for a syntactically valid email address: a non-empty local
68	     * part, a single '@', and a domain with at least one dot-separated label.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
72	
73	    /**
74	     * Common street-type abbreviations expanded during address normalization,
75	     * keyed by their upper-cased form.
76	     */
77	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
78	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
116	        Owner owner = this.clinicService.findOwnerById(ownerId);
117	        if (owner == null) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
126	        // Validate & normalize the optional email; reject the create when it is present but invalid.
127	        if (!normalizeEmail(ownerFieldsDto)) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
131	        // abbreviations) and store the normalized form back on the DTO so it is what gets
132	        // persisted and compared. Reject the create when the address is blank once normalized.
133	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
134	        if (canonicalAddress.isBlank()) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        ownerFieldsDto.setAddress(canonicalAddress);
138	        // Reject the create when the owner's city is already at capacity, i.e. it already
139	        // contains 50 or more owners (compared case-insensitively).
140	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
144	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
145	        if (normalizedTelephone == null) {
146	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
147	        }
148	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
149	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
150	            .map(Owner::getTelephone)
151	            .map(OwnerRestControllerV1::toE164)
152	            .filter(existing -> existing != null)
153	            .anyMatch(normalizedTelephone::equals);
154	        if (telephoneInUse) {
155	            return new ResponseEntity<>(HttpStatus.CONFLICT);
156	        }
157	        // Reject the create when another owner already shares this owner's last name and address
158	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
159	        // sharing a household.
160	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
161	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
162	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
163	            boolean householdInUse = this.clinicService.findAllOwners().stream()
164	                .anyMatch(existing ->
165	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
166	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
167	            if (householdInUse) {
168	                return new ResponseEntity<>(HttpStatus.CONFLICT);
169	            }
170	        }
171	        // Determine the effective registration date — the value supplied on the request, or the
172	        // server's current date when none was supplied — and roll it forward to the next business
173	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
174	        // registration date (membership-number year segment, per-day create-limit) uses this
175	        // adjusted date.
176	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
177	        if (registrationDate == null) {
178	            registrationDate = LocalDate.now();
179	        }
180	        registrationDate = toBusinessDay(registrationDate);
181	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
182	        // owners have already been registered on this (adjusted) business day.
183	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
184	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
185	        }
186	        ownerFieldsDto.setTelephone(normalizedTelephone);
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        owner.setRegistrationDate(registrationDate);
190	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
191	        // letters of the city, the upper-cased first three letters of the last name, and a
192	        // per-city 4-digit sequence one greater than the number of owners already in that city.
193	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
194	        // Record how many existing owners already share this owner's first and last name
195	        // (compared case-insensitively) at the moment before this owner is created.
196	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
197	        this.clinicService.saveOwner(owner);
198	        // Emit an audit line recording the new owner's id, customer code and registration date.
199	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
200	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
201	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
202	        headers.setLocation(UriComponentsBuilder.newInstance()
203	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
204	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
205	    }
206	
207	    /**
208	     * Validate and normalize the optional owner email in place.
209	     *
210	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
211	     * When present it must be a syntactically valid address; a valid address is
212	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
213	     * present but syntactically invalid, so the caller can reject with 400.
214	     */
215	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
216	        String email = ownerFieldsDto.getEmail();
217	        if (email == null || email.isBlank()) {
218	            ownerFieldsDto.setEmail(null);
219	            return true;
220	        }
221	        String normalized = email.trim().toLowerCase(Locale.ROOT);
222	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
223	            return false;
224	        }
225	        ownerFieldsDto.setEmail(normalized);
226	        return true;
227	    }
228	
229	    /**
230	     * Normalize an owner address: trim, collapse each run of whitespace to a single
231	     * space, upper-case, and expand common street-type abbreviations
232	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
233	     * A {@code null} value normalizes to the empty string.
234	     */
235	    private static String normalizeAddress(String value) {
236	        if (value == null) {
237	            return "";
238	        }
239	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
240	        if (collapsed.isEmpty()) {
241	            return "";
242	        }
243	        String[] tokens = collapsed.split(" ");
244	        StringBuilder sb = new StringBuilder(collapsed.length());
245	        for (int i = 0; i < tokens.length; i++) {
246	            if (i > 0) {
247	                sb.append(' ');
248	            }
249	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
250	        }
251	        return sb.toString();
252	    }
253	
254	    /**
255	     * Normalize an owner household field (last name or address) for duplicate detection:
256	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
257	     * A {@code null} value normalizes to the empty string.
258	     */
259	    private static String normalizeHouseholdKey(String value) {
260	        if (value == null) {
261	            return "";
262	        }
263	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
264	    }
265	
266	    /**
267	     * Normalize a telephone number to E.164 form.
268	     *
269	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
270	     * explicit leading {@code '+'} and country code it is kept; otherwise the
271	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
272	     * dropped from the national digits. The result must contain 8 to 15 digits
273	     * after the {@code '+'}.
274	     *
275	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
276	     *         the input is absent or cannot form a valid E.164 number.
277	     */
278	    private static String toE164(String raw) {
279	        if (raw == null) {
280	            return null;
281	        }
282	        String trimmed = raw.trim();
283	        boolean hasCountryCode = trimmed.startsWith("+");
284	        // Strip spaces, dashes and brackets.
285	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
286	        String digits;
287	        if (hasCountryCode) {
288	            // Keep the explicit country code; drop the leading '+' for validation.
289	            digits = stripped.substring(1);
290	        } else {
291	            // No country code: assume '+61' and drop a single leading '0'.
292	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
293	            digits = "61" + national;
294	        }
295	        if (!digits.matches("\\d{8,15}")) {
296	            return null;
297	        }
298	        return "+" + digits;
299	    }
300	
301	    /**
302	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
303	     *
304	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
305	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
306	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
307	     * equal to one more than the number of owners already in that city
308	     * (e.g. {@code 'SYD-SMI-0007'}).
309	     */
310	    /**
311	     * Count the existing owners whose first and last name match the given names,
312	     * compared case-insensitively. Used to record an owner's namesake count at the
313	     * moment before it is created.
314	     */
315	    private int countNamesakes(String firstName, String lastName) {
316	        return (int) this.clinicService.findAllOwners().stream()
317	            .filter(existing -> existing.getFirstName() != null
318	                && existing.getFirstName().equalsIgnoreCase(firstName)
319	                && existing.getLastName() != null
320	                && existing.getLastName().equalsIgnoreCase(lastName))
321	            .count();
322	    }
323	
324	    private String nextCustomerCode(String city, String lastName) {
325	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
326	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
327	        int sequence = countOwnersInCity(city) + 1;
328	        return String.format("%s-%s-%04d", city3, last3, sequence);
329	    }
330	
331	    /**
332	     * Count the existing owners located in the given city, compared case-insensitively.
333	     * Used to derive the per-city 4-digit sequence in the customer code.
334	     */
335	    private int countOwnersInCity(String city) {
336	        return (int) this.clinicService.findAllOwners().stream()
337	            .filter(existing -> existing.getCity() != null
338	                && existing.getCity().equalsIgnoreCase(city))
339	            .count();
340	    }
341	
342	    /**
343	     * Count the existing owners whose registration date is the given (adjusted business) date.
344	     * Used to enforce the per-day sign-up limit.
345	     */
346	    private int countOwnersRegisteredOn(LocalDate date) {
347	        return (int) this.clinicService.findAllOwners().stream()
348	            .filter(existing -> date.equals(existing.getRegistrationDate()))
349	            .count();
350	    }
351	
352	    /**
353	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
354	     * the following Monday; a weekday is returned unchanged.
355	     */
356	    private static LocalDate toBusinessDay(LocalDate date) {
357	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
358	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
359	            date = date.plusDays(1);
360	        }
361	        return date;
362	    }
363	
364	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
365	    @Override
366	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
367	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
368	        if (currentOwner == null) {
369	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
370	        }
371	        if (!normalizeEmail(ownerFieldsDto)) {
372	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
373	        }
374	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
375	        if (normalizedTelephone == null) {
376	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
377	        }
378	        currentOwner.setAddress(ownerFieldsDto.getAddress());
379	        currentOwner.setCity(ownerFieldsDto.getCity());
380	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
381	        currentOwner.setLastName(ownerFieldsDto.getLastName());
382	        currentOwner.setTelephone(normalizedTelephone);
383	        currentOwner.setEmail(ownerFieldsDto.getEmail());
384	        this.clinicService.saveOwner(currentOwner);
385	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
386	    }
387	
388	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
389	    @Transactional
390	    @Override
391	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
392	        Owner owner = this.clinicService.findOwnerById(ownerId);
393	        if (owner == null) {
394	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
395	        }
396	        this.clinicService.deleteOwner(owner);
397	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
398	    }
399	
400	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
401	    @Override
402	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
403	        Owner owner = this.clinicService.findOwnerById(ownerId);
404	        if (owner == null) {
405	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
406	        }
407	        HttpHeaders headers = new HttpHeaders();
408	        Pet pet = petMapper.toPet(petFieldsDto);
409	        owner.setId(ownerId);
410	        pet.setOwner(owner);
411	        pet.getType().setName(null);
412	        this.clinicService.savePet(pet);
413	        PetDto petDto = petMapper.toPetDto(pet);
414	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
415	            .buildAndExpand(pet.getId()).toUri());
416	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
417	    }
418	
419	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
420	    @Override
421	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
422	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
423	        if (currentOwner != null) {
424	            Pet currentPet = this.clinicService.findPetById(petId);
425	            if (currentPet != null) {
426	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
427	                currentPet.setName(petFieldsDto.getName());
428	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
429	                this.clinicService.savePet(currentPet);
430	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
431	            }
432	        }
433	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
434	    }
435	
436	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
437	    @Override
438	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
439	        HttpHeaders headers = new HttpHeaders();
440	        Visit visit = visitMapper.toVisit(visitFieldsDto);
441	        Pet pet = new Pet();
442	        pet.setId(petId);
443	        visit.setPet(pet);
444	        this.clinicService.saveVisit(visit);
445	        VisitDto visitDto = visitMapper.toVisitDto(visit);
446	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
447	            .buildAndExpand(visit.getId()).toUri());
448	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
449	    }
450	
451	
452	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
453	    @Override
454	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
455	        Owner owner = this.clinicService.findOwnerById(ownerId);
456	        if (owner != null) {
457	            Pet pet = owner.getPet(petId);
458	            if (pet != null) {
459	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
460	            }
461	        }
